<template><div class="page"><div class="page-header"><h2>自助报修</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="request_id" label="报修单号" width="120"/><el-table-column label="客户" width="100"><template #default="{row}">{{ custCard(row.custcd) }}</template></el-table-column><el-table-column prop="fault_desc" label="故障描述" min-width="150" show-overflow-tooltip/><el-table-column prop="eid" label="设备SN" width="120"/><el-table-column label="紧急程度" width="80"><template #default="{row}"><el-tag :type="urgencyTag(row.urgency)" size="small">{{ row.urgency||'NORMAL' }}</el-tag></template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="statusTag(row.status)" size="small">{{ row.status||'SUBMITTED' }}</el-tag></template></el-table-column><el-table-column prop="submit_time" label="提交时间" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'报修 — '+(detail?.request_id||'')" v-model="drawer" width="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="报修单号">{{ detail.request_id }}</el-descriptions-item><el-descriptions-item label="客户">{{ custCard(detail.custcd) }}</el-descriptions-item><el-descriptions-item label="设备SN">{{ detail.eid||'-' }}</el-descriptions-item><el-descriptions-item label="紧急程度">{{ detail.urgency||'NORMAL' }}</el-descriptions-item><el-descriptions-item label="联系人">{{ detail.contact_name||'-' }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ detail.contact_phone||'-' }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.status||'-' }}</el-descriptions-item><el-descriptions-item label="关联工单">{{ detail.maintenance_id||'-' }}</el-descriptions-item><el-descriptions-item label="故障描述" :span="2">{{ detail.fault_desc||'-' }}</el-descriptions-item><el-descriptions-item label="服务地址" :span="2">{{ detail.address||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {useCustomerCards} from '@/composables/useCustomerCards';import {fetchRepairRequests} from '@/api/portal';import type {PortalRecord} from '@/api/portal'
const{items,loading,page,perPage,total}=useListPage<PortalRecord>(fetchRepairRequests);const{drawer,detail,open}=useDetailDrawer<PortalRecord>();const{custCard}=useCustomerCards()
function urgencyTag(u:string){const m:Record<string,string>={LOW:'info',NORMAL:'',HIGH:'warning',URGENT:'danger'};return m[u]||'info'}
function statusTag(s:string){const m:Record<string,string>={SUBMITTED:'info',ACCEPTED:'warning',PROCESSING:'primary',COMPLETED:'success',CANCELLED:'danger'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
